#include <stdio.h>

static int freq[1000001];

int main(void) {
    int N, S;
    scanf("%d", &N);
    scanf("%d", &S);

    freq[0] = 1;

    int prefix = 0;
    long long ans = 0;

    for (int i = 0; i < N; i++) {
        int x;
        scanf("%d", &x);
        prefix += x;

        if (prefix >= S) {
            ans += freq[prefix - S];
        }

        freq[prefix]++;
    }

    printf("%lld\n", ans);
    return 0;
}
